import { useDispatch, useSelector } from "react-redux";
import "./UploadPhoto.css";
import {
  AddNewPhoto,
  deletePhoto,
  selectPhoto,
  SelectPhotoToMain,
  selectUser,
} from "../../../../store/slices/UserSlice";
import { useEffect, useState } from "react";
import CrossLogo from "../../../../SVG/CrossLogo";
const UploadPhoto = () => {
  const dispatch = useDispatch();
  const [uploadedPhoto, setUploadedPhoto] = useState(null);
  const [key, setKey] = useState(false);
  const { profile } = useSelector(selectUser);
  const handleFileUpload = async (event) => {
    const file = event.target.files[0];
    const formData = new FormData();
    formData.append('photo', file);
  
    try {
      const response = await fetch('http://localhost:8000/api/upload-photo', {
        method: 'POST',
        body: formData,
      });
  
      const data = await response.json();
  
      if (response.ok) {
        const newPhoto = { url: data.url, key: false, active: true };
  
        const updatedProfile = {
          ...profile,
          Photo: [...(profile.Photo || []), newPhoto],
        };
  
        // Сохраняем в Laravel через PATCH
        await fetch(`http://localhost:8000/api/users/${profile.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(updatedProfile),
        });
  
        // Можно также обновить Redux, если нужно
        dispatch(selectPhoto(updatedProfile.Photo.length - 1));
      }
    } catch (error) {
      console.error('Ошибка при загрузке:', error);
    }
  };

  console.log(profile);
  

  useEffect(() => {
    if (!profile?.id) return;
  
    fetch(`http://localhost:8000/api/users/${profile.id}`, {
      method: "PATCH",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify(profile),
    });
  }, [key]);


  fetch('http://localhost:8000/api/get-photos')
  .then(response => response.json())
  .then(photos => {
    photos.forEach(photo => {
     
      console.log(photo);  
    });
  })
  .catch(error => {
    console.error('Error fetching photos:', error);
  });
  const handlerDeletePhoto = async(index) => { 
    

    
    const newresult = {
      ...profile,
      Photo: profile.Photo.filter((el,indexEl) => index != indexEl)
      
    };
      const endRes = await fetch(`http://localhost:8000/api/users/${profile.id}`, {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(newresult),
      });
      return endRes;
  }


  return (
    <div className="UploadPhoto">
      {profile?.Photo?.map((el, index) => {
  if (el.active) {
    return (
      <header className="Selected-Photo" key={index}>
        <div className="Selected-Image">
          <div>
            <i onClick={() => dispatch(selectPhoto(index))}>
              <CrossLogo />
            </i>
          </div>
          <img src={el.url} alt="photo" />
          <div className="Selected-Image-Buttons">
            <button
              onClick={() => {
                dispatch(deletePhoto(index));
                handlerDeletePhoto(index);
              }}
            >
              Delete
            </button>
            <button
              onClick={() => {
                dispatch(SelectPhotoToMain(index));
                setKey(true);
              }}
            >
              Add As Main Photo
            </button>
          </div>
        </div>
      </header>
    );
  } else {
    return (
      <p>No Photos</p>
    );
  }
})}
      <div>
        <form
          onSubmit={(e) => {
            e.preventDefault();
            e.target.reset();
          }}
        >
          <input
            type="file"
            name="myImage"
            onChange={(event) => handlePhotoUpload(event)}
          />
          <button onClick={handleFileUpload }>Upload</button>
        </form>
      </div>
      <div className="MyPhotos">
      <div className="MyPhotos">
  {profile?.Photo?.length === 0 ? (
    <p>No Photos</p>
  ) : (
    profile?.Photo?.map((photo, index) => (
      <img
        onClick={() => dispatch(selectPhoto(index))}
        src={photo.url}
        alt="photo"
        key={index}
      />
    ))
  )}
</div>
      </div>
    </div>
  );
};

export default UploadPhoto;
